func SkMinConf() int32 {
	// `script-conf`: OSD's script confidence (x10) from which kin believes the script it names (a Latin page reads 10 to 20, the Hindi page of the smoke review 63).
	return 150
}

func SkWeakConf() int32 {
	// `script-weak-conf` (R2): from this OSD script confidence (x10) kin believes a script OSD names, when the engine's dictionary also knows few of the words (`sk-dict-share`): the gate of 15 missed Urdu, Han, Ethiopic.
	return 50
}

func SkDictShare() int32 {
	// `script-dict-share` (R2): ...few is under this share (per mille) of the words read from the engine's dictionary.
	return 250
}

func SkMinWords() int32 {
	// A page of fewer OCR words than this is not flagged: the engine read nothing of it that could be junk.
	return 3
}

func SkUnpack(lang int32, out *port.Cells) int32 {
	// The language cell `lang` (up to four ASCII chars, packed big-endian) as code points in `out` (emptied first). Answers how many.
	var d int32 = 16777216
	var b int32 = 0
	var n int32 = 0
	port.CellsDrop(out, 0)
	for d > 0 {
		b = (lang / d) % 256
		if b != 0 {
			port.CellsPush(out, b)
			n += 1
		}
		d = d / 256
	}
	return n
}

func skDict(nw int32, an *port.Cells, ext int32) int32 {
	// How many of the answer's `nw` words the engine read from its dictionary.
	var w int32 = ocr.OxFirstWord(an, ext)
	var i int32 = 0
	var k int32 = 0
	for i < nw {
		if (ocr.OxWdflags(an, w) & ocr.OcwDict()) != 0 {
			k += 1
		}
		w = ocr.OxWordNext(an, w)
		i += 1
	}
	return k
}

func SkUnread(an *port.Cells, at int32, scr *port.Cells) int32 {
	// 1 when the page the OCR answer at `at` read is in a script the engine had no model for (see the head of this file), else 0. `scr` is scratch.
	var ext int32 = ocr.OxFind(an, at)
	var nw int32 = plan.AnOcrCount(an, at)
	var w int32 = 0
	var i int32 = 0
	var lang int32 = 0
	var n int32 = 0
	var script int32 = 0
	if ext < 0 {
		return 0
	}
	script = ocr.OxScript(an, ext)
	if script <= 0 {
		return 0
	}
	if script == ocrport.ScLatn() {
		return 0
	}
	if script == ocrport.ScLatf() {
		return 0
	}
	if ocr.OxSconf(an, ext) < SkWeakConf() {
		return 0
	}
	if nw < SkMinWords() {
		return 0
	}
	// P12.6 (R2): OSD names the script of an Urdu, a Han photo or an Ethiopic page in a legacy font at a confidence under `sk-min-conf`; its word is then believed only when the
	// reading backs it: a page whose words the engine's dictionary knows (`sk-dict-share` or more of them) is Latin, whatever OSD says; a page it knows few words of is junk in a script it cannot read.
	if ocr.OxSconf(an, ext) < SkMinConf() {
		if (skDict(nw, an, ext) * 1000) >= (nw * SkDictShare()) {
			return 0
		}
	}
	w = ocr.OxFirstWord(an, ext)
	for i < nw {
		lang = ocr.OxWlang(an, w)
		if lang > 0 {
			n = SkUnpack(lang, scr)
			if ocrport.OpScriptReads(script, ocrport.OpModelScript(scr, 0, n)) == 1 {
				return 0
			}
		}
		w = ocr.OxWordNext(an, w)
		i += 1
	}
	return 1
}

func SkRoute(ans *port.Cells, at int32, id int32, bitmap int32, dpi int32, rq *port.Cells, scr *port.Cells) int32 {
	// An unread first pass is retried once in the script OSD named plus English. `op-models` in kin selects the installed
	// models; a missing script model leaves English and `sk-unread` still flags the answer. -1 means the request needs an answer.
	if SkUnread(ans, at, scr) == 0 {
		return at
	}
	var found int32 = plan.AnFind(ans, id)
	var ext int32 = ocr.OxFind(ans, at)
	var script int32 = ocr.OxScript(ans, ext)
	if found >= 0 {
		if plan.AnOk(ans, found) == 1 {
			return found
		}
		return at
	}
	var q int32 = plan.RqOcr(rq, id, bitmap, 3, (ocr.OcfSymbols()+ocr.OcfOsd())+(dpi*ocr.OcfDpiUnit()), 0, 0, 0, 0)
	plan.RqOcrLang(rq, script/16777216, (script/65536)%256, (script/256)%256, script%256)
	plan.RqOcrLang(rq, 101, 110, 103, 0)
	plan.RqOcrEnd(rq, q)
	return -1
}

